CREATE TABLE public.complaint_vulnerability(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,complaint_id uuid NOT NULL UNIQUE REFERENCES public.complaints(id) ON DELETE CASCADE,drivers text[] NOT NULL DEFAULT '{}',adjustments text[] NOT NULL DEFAULT '{}',adjustments_note text CHECK(length(adjustments_note)<=500),assessed_by uuid,assessed_at timestamptz NOT NULL DEFAULT now(),review_by date,customer_consented boolean NOT NULL DEFAULT false,source text NOT NULL DEFAULT 'agent' CHECK(source IN ('customer','agent')),CHECK(drivers <@ ARRAY['health','life_event','resilience','capability','other']::text[]),CHECK(adjustments <@ ARRAY['extra_time','alternative_format','preferred_channel','language_support','trusted_third_party','simplified_language','other']::text[]));
GRANT SELECT,INSERT,UPDATE ON public.complaint_vulnerability TO authenticated;
GRANT ALL ON public.complaint_vulnerability TO service_role;
ALTER TABLE public.complaint_vulnerability ENABLE ROW LEVEL SECURITY;
CREATE POLICY support_read ON public.complaint_vulnerability FOR SELECT TO authenticated USING(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager','qa_reviewer']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=complaint_vulnerability.org_id AND c.assigned_to=auth.uid())));
CREATE POLICY support_insert ON public.complaint_vulnerability FOR INSERT TO authenticated WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=complaint_vulnerability.org_id AND c.assigned_to=auth.uid())));
CREATE POLICY support_update ON public.complaint_vulnerability FOR UPDATE TO authenticated USING(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=complaint_vulnerability.org_id AND c.assigned_to=auth.uid()))) WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=complaint_vulnerability.org_id AND c.assigned_to=auth.uid())));
CREATE FUNCTION public.support_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.complaints; BEGIN SELECT * INTO c FROM public.complaints WHERE id=NEW.complaint_id AND org_id=NEW.org_id FOR UPDATE; IF c.id IS NULL OR c.legal_hold OR c.privacy_processing OR c.anonymised_at IS NOT NULL OR c.status='closed' THEN RAISE EXCEPTION 'This complaint is locked'; END IF; IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.org_id<>OLD.org_id OR NEW.complaint_id<>OLD.complaint_id) THEN RAISE EXCEPTION 'Support identity cannot change'; END IF; IF current_user IN ('authenticated','anon') THEN NEW.assessed_by:=auth.uid(); NEW.source:='agent'; END IF; NEW.assessed_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER support_guard BEFORE INSERT OR UPDATE ON public.complaint_vulnerability FOR EACH ROW EXECUTE FUNCTION public.support_guard();
CREATE TRIGGER support_privacy_guard BEFORE INSERT OR UPDATE ON public.complaint_vulnerability FOR EACH ROW EXECUTE FUNCTION public.privacy_child_guard();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.audit_minimise(text,jsonb)'::regprocedure) INTO def; def:=replace(def,'ELSE _row END','WHEN _table=''complaint_vulnerability'' THEN _row-ARRAY[''drivers'',''adjustments_note''] ELSE _row END'); EXECUTE def; END $$;
CREATE TRIGGER support_audit AFTER INSERT OR UPDATE OR DELETE ON public.complaint_vulnerability FOR EACH ROW EXECUTE FUNCTION public.audit_capture();
ALTER TABLE public.complaint_vulnerability DISABLE TRIGGER support_guard;
ALTER TABLE public.complaint_vulnerability DISABLE TRIGGER support_privacy_guard;
INSERT INTO public.complaint_vulnerability(org_id,complaint_id,drivers,adjustments_note,source,customer_consented) SELECT org_id,id,ARRAY['other'],left(vulnerable_note,500),'agent',false FROM public.complaints WHERE (vulnerable OR nullif(trim(vulnerable_note),'') IS NOT NULL) AND anonymised_at IS NULL;
ALTER TABLE public.complaint_vulnerability ENABLE TRIGGER support_guard;
ALTER TABLE public.complaint_vulnerability ENABLE TRIGGER support_privacy_guard;
CREATE FUNCTION public.support_sync() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE previous text; oldreason text; BEGIN previous:=current_setting('redress.detail_case',true); oldreason:=current_setting('redress.detail_reason',true); PERFORM set_config('redress.detail_case',NEW.complaint_id::text,true); PERFORM set_config('redress.detail_reason','Support needs assessment updated',true); PERFORM set_config('redress.detail_diff','{}',true); UPDATE public.complaints SET vulnerable=cardinality(NEW.drivers)>0 WHERE id=NEW.complaint_id AND org_id=NEW.org_id AND vulnerable IS DISTINCT FROM (cardinality(NEW.drivers)>0); PERFORM set_config('redress.detail_case',coalesce(previous,''),true); PERFORM set_config('redress.detail_reason',coalesce(oldreason,''),true); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.support_sync() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER support_sync AFTER INSERT OR UPDATE ON public.complaint_vulnerability FOR EACH ROW EXECUTE FUNCTION public.support_sync();
CREATE FUNCTION public.support_flag_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN NEW.vulnerable:=NEW.anonymised_at IS NULL AND EXISTS(SELECT 1 FROM public.complaint_vulnerability WHERE complaint_id=NEW.id AND org_id=NEW.org_id AND cardinality(drivers)>0); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.support_flag_guard() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER zz_support_flag BEFORE UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.support_flag_guard();
CREATE FUNCTION public.support_seed() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.vulnerable THEN INSERT INTO public.complaint_vulnerability(org_id,complaint_id,drivers,source,assessed_by) VALUES(NEW.org_id,NEW.id,ARRAY['other'],'agent',auth.uid()); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.support_seed() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER support_seed AFTER INSERT ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.support_seed();
CREATE FUNCTION public.support_anonymise() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.anonymised_at IS NULL AND NEW.anonymised_at IS NOT NULL THEN DELETE FROM public.complaint_vulnerability WHERE complaint_id=NEW.id AND org_id=NEW.org_id; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.support_anonymise() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER support_anonymise AFTER UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.support_anonymise();
CREATE FUNCTION public.support_delete_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF current_user IN ('authenticated','anon') THEN RAISE EXCEPTION 'Use authorised privacy erasure'; END IF; RETURN OLD; END $$;
CREATE TRIGGER support_no_delete BEFORE DELETE ON public.complaint_vulnerability FOR EACH ROW EXECUTE FUNCTION public.support_delete_guard();
DO $$ DECLARE def text; original text; BEGIN SELECT pg_get_functiondef('public.submit_public_complaint(uuid,uuid,jsonb)'::regprocedure) INTO original; def:=replace(original,'''en'',''fr'',''es'',''pt'',''pl'',''nl''','''en'',''fr'',''es'',''pt'',''pl'',''nl'',''de'',''it'',''lt'',''sv'',''da'',''cs'',''ro'',''ga'''); IF def=original THEN RAISE EXCEPTION 'Expected public language check not found'; END IF; def:=replace(def,'CASE WHEN (_data->>''vulnerable'')::boolean THEN nullif(trim(_data->>''vulnerable_note''),'''') END','NULL'); def:=replace(def,' RETURN ref;'||chr(10)||'END;',' IF (_data->>''vulnerable'')::boolean THEN IF coalesce(_data->>''customer_consented'',''false'') NOT IN (''true'',''false'') OR jsonb_typeof(coalesce(_data->''adjustments'',''[]''::jsonb))<>''array'' OR length(coalesce(_data->>''adjustments_note'',''''))>500 OR _data ? ''drivers'' THEN RAISE EXCEPTION ''Invalid support needs''; END IF; UPDATE public.complaint_vulnerability SET adjustments=ARRAY(SELECT jsonb_array_elements_text(coalesce(_data->''adjustments'',''[]''::jsonb))),adjustments_note=nullif(trim(_data->>''adjustments_note''),''''),customer_consented=coalesce((_data->>''customer_consented'')::boolean,false),source=''customer'',assessed_by=NULL WHERE complaint_id=c AND org_id=f.org_id; END IF;'||chr(10)||' RETURN ref;'||chr(10)||'END;'); EXECUTE def; END $$;
COMMENT ON COLUMN public.complaints.vulnerable_note IS 'DEPRECATED: use restricted complaint_vulnerability.adjustments_note; retained for compatibility only.';
CREATE INDEX support_org_review ON public.complaint_vulnerability(org_id,review_by);
NOTIFY pgrst,'reload schema';